		local items = ItemLibrary and ItemLibrary.Items
		local overrideWeaponStatus = getgenv().Elisium.Visuals["Override Weapon Status"]

		if type(items) == "table" then
			if not tbl54 then
				tbl54 = {}

				for k, item in pairs(items) do
					if type(item) == "table" and item.Status ~= nil then
