							character:WaitForChild("Humanoid")
							local v90 = players:CreateHumanoidModelFromUserIdAsync(arg)
							local pants = v90:FindFirstChild("Pants")
							local pants2 = character:FindFirstChild("Pants")

							if pants then
								if not pants2 then
									pants2 = Instance.new("Pants", character)
									pants2.Name = "Pants"
								end

								pants2.PantsTemplate = pants.PantsTemplate
							elseif pants2 then
