						if textChannels then
							textChannels = textChannels:FindFirstChild("RBXGeneral") or textChannels:FindFirstChild("RBXSystem")
						end

						if textChannels and textChannels:IsA("TextChannel") then
							if pcall(textChannels.DisplaySystemMessage, textChannels, string.format("<font color=\"#FFAA00\" face=\"SourceSansBold\">%s</font>", fn33(arg)), "ElisiumEndStreak") then
