					fn33 = function(arg)
						local str9 = (tostring(arg or ""):match("^%s*(.-)%s*$") or ""):gsub("^@", "")
						if str9 == "" then
							return nil, "enter a username or display name"
						end
						local str10 = str9:lower()
						local tbl58 = {}
						local v90 = nil

						for _, v91 in players:GetPlayers() do
							if v91.Name:lower() == str10 then
								v90 = v91
								break
							elseif v91.DisplayName:lower() ~= str10 then
								v90 = nil
							else
								tbl58[#tbl58 + 1] = v91
								v90 = nil
							end
						end

						if v90 then
							return fn34(v90), nil
						end

						if #tbl58 == 1 then
							return fn34(tbl58[1]), nil
						end

						if 1 < #tbl58 then
							return nil, "multiple players use that display name; enter a username"
						end
						local v91 = tbl57[str10]
						if v91 then
							return v91, nil
						end
						local ok, result = pcall(players.GetUserIdFromNameAsync, players, str9)
						if not ok or type(result) ~= "number" then
							return nil, "player not found; offline display names require a username"
						end
						local ok2, result2 = pcall(userService.GetUserInfosByUserIdsAsync, userService, { result })
						ok2 = ok2 and type(result2) == "table"
						local v92 = nil

						if ok2 then
							v92 = nil

							for _, v93 in result2, nil, nil do
								if type(v93) == "table" and v93.Id == result then
									v92 = v93
									break
								else
