								end
							end
						end

						local flag18 = type(v92) ~= "table"

						if not flag18 then
							local v93 = "string"
							flag18 = type(v92.Username) ~= v93
						end

						local flag19

						if flag18 then
							flag19 = flag18
						else
							local v93 = "string"
							flag19 = type(v92.DisplayName) ~= v93
						end

						if flag19 then
							return nil, "failed to load that account's username and display name"
						end
						local tbl59 = { UserId = result, Name = v92.Username, DisplayName = v92.DisplayName }
						tbl57[str10] = tbl59
						tbl57[tbl59.Name:lower()] = tbl59
						return tbl59, nil
					end
				end
			end

