					end

					str8 ..= str9:lower()
				end

				return str8
			end

			do
				local tbl55 = {
					["DARKMODE V3.5"] = game:GetService("HttpService"):JSONDecode("<blob #8: JSON, 4808 chars, see blobs.json>"),
					Shadownaught = game:GetService("HttpService"):JSONDecode("<blob #9: JSON, 2120 chars, see blobs.json>"),
					["Bone skins"] = game:GetService("HttpService"):JSONDecode("<blob #10: JSON, 4206 chars, see blobs.json>"),
					["Minecraft Classic (night)"] = game:GetService("HttpService"):JSONDecode("<blob #11: JSON, 27168 chars, see blobs.json>"),
					Crimvals = game:GetService("HttpService"):JSONDecode("<blob #12: JSON, 34120 chars, see blobs.json>"),
